/**
 * Reference image and multimodal message builder for illustration generation.
 * The base64 constant below is the deep-dives.png feature image used as a style
 * anchor so that every generated illustration matches the same visual series.
 */

export const REFERENCE_IMAGE_BASE64 = "";

const STYLE_PREFIX =
  "Use the attached image as a style reference for colour warmth, rendering quality, and overall tone only. Do NOT copy its composition or top-down perspective. The overall tone should be warm and inviting with soft hand-painted quality and gentle lighting reminiscent of Studio Ghibli background art.\n\n";

/**
 * Build a multimodal messages array that pairs the reference image with the
 * given text prompt, suitable for the OpenRouter chat completions API.
 */
export function buildImageMessages(prompt: string) {
  return [
    {
      role: "user" as const,
      content: [
        {
          type: "image_url" as const,
          image_url: {
            url: `data:image/png;base64,${REFERENCE_IMAGE_BASE64}`,
          },
        },
        {
          type: "text" as const,
          text: STYLE_PREFIX + prompt,
        },
      ],
    },
  ];
}
